package generatorUtils;

/*Generated by MPS */

import org.jetbrains.mps.openapi.model.SNode;
import org.jetbrains.mps.openapi.model.SModel;

/**
 * Util class voor het afleiden van node- en model-IDs.
 */
public class IdUtil {
  public static String nodeId(SNode n) {
    return n.getNodeId().toString();
  }

  public static String fullNodeIdFromNode(SModel model, SNode node) {
    return escapedModelId(model) + "_" + node.getNodeId().toString();
  }



  public static String escapedModelId(SModel model) {
    String modelId = model.getModelId().toString();
    int idx = modelId.lastIndexOf(':');
    return ((idx + 1 < modelId.length() ? modelId.substring(idx + 1) : modelId)).replaceAll("-", "_");
  }


}
